<?php
require_once __DIR__.'/v5-common.php';$tickets=[];$error='';$notice='';$q=trim((string)($_GET['q']??''));$q=substr($q,0,100);$mine=isset($_GET['mine'])&&$_GET['mine']==='1';$user=(string)($_SESSION['username']??$_SESSION['usuario']??'');
if(empty($_SESSION['v5_csrf']))$_SESSION['v5_csrf']=bin2hex(random_bytes(32));
try{$db=v5db();if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['v5_csrf'],(string)($_POST['csrf']??'')))throw new InvalidArgumentException('Token CSRF inválido.');
 $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id||$id<1)throw new InvalidArgumentException('Chamado inválido.');
 $status=(string)($_POST['status']??'');$valid=['aberto','em_atendimento','aguardando','resolvido','fechado'];if(!in_array($status,$valid,true))throw new InvalidArgumentException('Status inválido.');
 $stmt=$db->prepare('SELECT assigned_to FROM sd_tickets WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$old=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$old)throw new RuntimeException('Chamado não localizado.');
 $note=trim((string)($_POST['note']??''));if(strlen($note)>3000)throw new InvalidArgumentException('Nota muito longa.');
 sdUpdate($db,$id,$status,(string)($old['assigned_to']??''),$note,$user);header('Location: service-desk-kanban.php?updated=1');exit;
 }
 $term='%'.addcslashes($q,'%_').'%';$st=$db->prepare("SELECT id,protocol,title,priority,status,assigned_to,created_at FROM sd_tickets WHERE (?='' OR protocol LIKE ? OR title LIKE ?) AND (?=0 OR assigned_to=?) ORDER BY FIELD(priority,'critica','alta','media','baixa'),created_at DESC LIMIT 250");$m=$mine?1:0;$st->bind_param('sssis',$q,$term,$term,$m,$user);$st->execute();$tickets=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();
}catch(Throwable $ex){error_log('[V5 kanban] '.$ex->getMessage());$error=$ex instanceof InvalidArgumentException?$ex->getMessage():'Não foi possível processar os chamados. Verifique o banco e as permissões.';}
v5head('Kanban de chamados');?><header class="v5-header"><div><div class="v5-kicker">Service Desk / Fluxo visual</div><h1>Kanban de chamados</h1><p>Visão por status. Alterações são registradas pela rotina auditável do Service Desk.</p></div><div class="v5-actions"><a class="v5-btn" href="central-operacoes.php">Central</a><a class="v5-btn" href="service-desk.php">Lista e filtros avançados</a></div></header>
<?php if($error):?><p class="v5-empty" role="alert"><?=v5e($error)?></p><?php endif;?><?php if(isset($_GET['updated'])):?><p class="v5-tag v5-success" role="status">Atualização registrada.</p><?php endif;?>
<form method="get" class="v5-panel v5-filters"><label>Pesquisar protocolo ou título<input name="q" value="<?=v5e($q)?>" maxlength="100"></label><label>Visão<select name="mine"><option value="0">Equipe</option><option value="1" <?=$mine?'selected':''?>>Meus chamados</option></select></label><button class="v5-btn v5-primary">Aplicar</button><a class="v5-btn" href="service-desk-kanban.php">Limpar</a></form>
<div class="v5-board" aria-label="Quadro de chamados"><?php foreach(['aberto'=>'Abertos','em_atendimento'=>'Em atendimento','aguardando'=>'Aguardando','resolvido'=>'Resolvidos','fechado'=>'Fechados'] as $status=>$label):$items=array_values(array_filter($tickets,static fn($t)=>$t['status']===$status));?><section class="v5-lane"><h2><?=v5e($label)?> <span><?=count($items)?></span></h2><?php foreach($items as $t):?><article class="v5-ticket"><a href="service-desk-detalhe.php?id=<?=(int)$t['id']?>"><strong><?=v5e($t['protocol'])?></strong></a><p><?=v5e($t['title'])?></p><small><?=v5e($t['assigned_to']?:'Sem responsável')?></small><div class="v5-foot"><span class="v5-tag <?=in_array($t['priority'],['critica','alta'],true)?'v5-danger':''?>"><?=v5e($t['priority'])?></span><a href="service-desk-detalhe.php?id=<?=(int)$t['id']?>">Detalhes →</a></div><details><summary>Atualizar status</summary><form method="post"><input type="hidden" name="csrf" value="<?=v5e($_SESSION['v5_csrf'])?>"><input type="hidden" name="id" value="<?=(int)$t['id']?>"><label>Novo status<select name="status"><?php foreach(['aberto','em_atendimento','aguardando','resolvido','fechado'] as $v):?><option <?=$v===$status?'selected':''?> value="<?=v5e($v)?>"><?=v5e(str_replace('_',' ',$v))?></option><?php endforeach;?></select></label><label>Justificativa (obrigatória para resolução, fechamento ou reabertura)<input name="note" maxlength="3000"></label><button class="v5-btn v5-primary">Registrar</button></form></details></article><?php endforeach;?><?php if(!$items):?><p class="v5-subtle">Sem chamados nesta coluna.</p><?php endif;?></section><?php endforeach;?></div><p class="v5-subtle">O quadro mostra até 250 registros filtrados. Para atribuir responsáveis ou editar informações completas, use a página de detalhes. As movimentações exigem confirmação: não há arrastar-e-soltar silencioso.</p><?php v5foot();?>
